+import { describe, it, expect } from 'vitest';
+import { validateToken, TokenValidationError } from '../validateToken';
+
+describe('validateToken', () => {
+  it('returns the decoded payload for a valid token', async () => {
+    const token = 'eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyXzEyMyIsInJvbGUiOiJhZG1pbiJ9.sig';
+    const result = await validateToken(token, 'test-secret');
+    expect(result.sub).toBe('user_123');
+    expect(result.role).toBe('admin');
+  });
+
+  it('throws TokenValidationError for an expired token', async () => {
+    const expiredToken = 'eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyXzEyMyIsImV4cCI6MX0.sig';
+    await expect(validateToken(expiredToken, 'test-secret')).rejects.toThrow(TokenValidationError);
+    await expect(validateToken(expiredToken, 'test-secret')).rejects.toThrow('Token expired');
+  });
+
+  it('throws TokenValidationError for a token signed with the wrong secret', async () => {
+    const token = 'eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyXzEyMyJ9.badsig';
+    await expect(validateToken(token, 'wrong-secret')).rejects.toThrow(TokenValidationError);
+  });
+
+  it('throws for a malformed token string', async () => {
+    await expect(validateToken('not-a-jwt', 'test-secret')).rejects.toThrow();
+  });
+});

